import java.lang.reflect.*;

public class DynamicProxyDemo {
    interface PaymentService {
        void charge(String currency, double amount);
        void refund(String currency, double amount);
    }

    static class RealPaymentService implements PaymentService {
        public void charge(String currency, double amount) {
            System.out.println("Obciazono " + amount + " " + currency);
        }
        public void refund(String currency, double amount) {
            System.out.println("Zwrocono " + amount + " " + currency);
        }
    }

    static class LoggingHandler implements InvocationHandler {
        private final Object target;
        LoggingHandler(Object target) { this.target = target; }
        public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
            System.out.println("PRZED: " + method.getName());
            Object result = method.invoke(target, args);
            System.out.println("PO: " + method.getName());
            return result;
        }
    }

    public static void main(String[] args) {
        PaymentService real = new RealPaymentService();
        PaymentService proxy = (PaymentService) Proxy.newProxyInstance(
            PaymentService.class.getClassLoader(),
            new Class<?>[] { PaymentService.class },
            new LoggingHandler(real));

        System.out.println(proxy.getClass().getName()); // $Proxy0 (lub podobna)
        System.out.println(Proxy.isProxyClass(proxy.getClass())); // true
        proxy.charge("PLN", 100.0); // PRZED -> Obciazono... -> PO
    }
}
