class MetricsHandler implements InvocationHandler {
    private final Object target;
    private final Map<String, long[]> stats = new HashMap<>();
    MetricsHandler(Object target) { this.target = target; }
    public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
        long start = System.nanoTime();
        Object result = method.invoke(target, args);
        long elapsed = System.nanoTime() - start;
        stats.computeIfAbsent(method.getName(), k -> new long[2]);
        long[] entry = stats.get(method.getName());
        entry[0]++; entry[1] += elapsed;
        return result;
    }
    void printReport() {
        for (var e : stats.entrySet()) {
            long count = e.getValue()[0];
            long avgMicros = (e.getValue()[1] / count) / 1000;
            System.out.println(e.getKey() + " | " + count + " | " + avgMicros + " us");
        }
    }
}

class CircuitBreakerHandler implements InvocationHandler {
    private final Object target;
    private int consecutiveFailures = 0;
    private static final int THRESHOLD = 3;
    CircuitBreakerHandler(Object target) { this.target = target; }
    public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
        if (consecutiveFailures >= THRESHOLD) {
            throw new IllegalStateException("Obwod otwarty - wywolania zablokowane");
        }
        try {
            Object result = method.invoke(target, args);
            consecutiveFailures = 0;
            return result;
        } catch (InvocationTargetException e) {
            consecutiveFailures++;
            throw e.getCause();
        }
    }
}

