class CompositeHandler implements InvocationHandler {
    private final Object target;
    private final java.util.List<java.util.function.Consumer<Method>> beforeHooks = new java.util.ArrayList<>();
    CompositeHandler(Object target) { this.target = target; }
    void addHook(java.util.function.Consumer<Method> hook) { beforeHooks.add(hook); }
    public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
        for (var hook : beforeHooks) hook.accept(method);
        return method.invoke(target, args);
    }
}

