// argument - proba przekazania klasy konkretnej (np. RealPaymentService.class) zamiast interfejsu
// zakonczylaby sie bledem w runtime (IllegalArgumentException: RealPaymentService is not an interface),
// bo mechanizm ten generuje NOWA klase IMPLEMENTUJACA dany interfejs, nie ROZSZERZAJACA istniejaca klase.
// Zeby proxowac KLASY konkretne (bez interfejsu), prawdziwy framework (jak Spring AOP) uzylby narzedzia
// generujacego BAJTKOD w locie, np. CGLIB lub ByteBuddy - one tworza PODKLASE danej klasy w czasie
// dzialania, nadpisujac wszystkie jej metody, co jest technicznie zupelnie innym mechanizmem niz
// java.lang.reflect.Proxy, mimo ze koncepcyjnie sluzy do tego samego celu.

Greeter real = new EnglishGreeter();
Greeter proxy = (Greeter) Proxy.newProxyInstance(
    Greeter.class.getClassLoader(), new Class<?>[]{Greeter.class}, new DelegatingHandler(real));

long t1 = System.nanoTime();
for (int i = 0; i < 200_000; i++) real.greet("x");
long directTime = System.nanoTime() - t1;

long t2 = System.nanoTime();
for (int i = 0; i < 200_000; i++) proxy.greet("x");
long proxyTime = System.nanoTime() - t2;

double overheadPercent = ((double) (proxyTime - directTime) / directTime) * 100;
System.out.println("Narzut proxy: " + overheadPercent + "%");
// Potwierdza Ryzyko 1 z Lesson16 - proxy jest zbudowane na refleksji (method.invoke wewnatrz handlera),
// wiec dziedziczy jej narzut wydajnosciowy w porownaniu do wywolania bezposredniego.

@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.METHOD)
@interface Logged {}

interface OrderService {
    void placeOrder(String item);
    void cancelOrder(String item);
    String getStatus();
}

class RealOrderService implements OrderService {
    @Logged
    public void placeOrder(String item) { System.out.println("Zamowienie: " + item); }
    public void cancelOrder(String item) { System.out.println("Anulowano: " + item); }
    @Logged
    public String getStatus() { return "OK"; }
}

@SuppressWarnings("unchecked")
static <T> T createAopProxy(T target, Class<T> interfaceType) {
    return (T) Proxy.newProxyInstance(interfaceType.getClassLoader(), new Class<?>[]{interfaceType},
        (proxy, method, args) -> {
            Method implMethod = target.getClass().getMethod(method.getName(), method.getParameterTypes());
            boolean logged = implMethod.isAnnotationPresent(Logged.class);
            if (logged) System.out.println("PRZED: " + method.getName());
            Object result = method.invoke(target, args);
            if (logged) System.out.println("PO: " + method.getName());
            return result;
        });
}

OrderService proxy = createAopProxy(new RealOrderService(), OrderService.class);
proxy.placeOrder("Laptop"); // logowane
proxy.cancelOrder("Laptop"); // NIE logowane
proxy.getStatus(); // logowane
